import type { TourPackagePageDetail } from "@/types/tour-package-detail";

/** DOM ids for anchor navigation + scroll spy (day-tour section set). */
export const SECTION_NAV: { domId: string; label: string }[] = [
  { domId: "tour-overview", label: "Overview" },
  { domId: "tour-highlights", label: "Highlights" },
  { domId: "tour-itinerary", label: "Itinerary" },
  { domId: "tour-inclusions", label: "Inclusions" },
  { domId: "tour-accommodation", label: "Accommodation" },
  { domId: "tour-date-price", label: "Date & Price" },
  { domId: "tour-reviews", label: "Reviews" },
];

export function formatUsd(value: number) {
  return value.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  });
}

export function formatUsdFull(value: number) {
  return value.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

export type DatePriceSort = "startAsc" | "startDesc" | "priceAsc" | "priceDesc";

export function parseDateLabel(value: string) {
  const direct = Date.parse(value);
  if (!Number.isNaN(direct)) return direct;
  const withoutWeekday = value.replace(/^[A-Za-z]+\s+/, "");
  const fallback = Date.parse(withoutWeekday);
  if (!Number.isNaN(fallback)) return fallback;
  return 0;
}

export function dayTourItineraryCardTitle(detail: TourPackagePageDetail): string {
  const custom = detail.dayItineraryCardTitle?.trim();
  if (custom) return custom;
  return detail.itinerary.map((d) => d.title).filter(Boolean).join(" — ");
}

export function dayTourTransportPillText(detail: TourPackagePageDetail): string {
  const custom = detail.dayTourTransportPill?.trim();
  if (custom) return custom;
  const ref = `${detail.sidebar.destination} ${detail.routeLabel}`.toLowerCase();
  if (ref.includes("cairo") || ref.includes("giza")) {
    return "To and from your hotel in Cairo or Giza, and throughout the tour between locations";
  }
  return "Hotel pickup and drop-off, and private transport throughout your tour.";
}

export function dayTourMealsPillText(detail: TourPackagePageDetail): string {
  const custom = detail.dayTourMealsPill?.trim();
  if (custom) return custom;
  if (detail.durationLabel.toLowerCase().includes("half")) {
    return "Meals at your discretion unless noted";
  }
  const inc = detail.inclusions.join(" ").toLowerCase();
  if (inc.includes("lunch")) return "Lunch at a local restaurant";
  const last = detail.itinerary[detail.itinerary.length - 1];
  if (last?.meals) return last.meals;
  return "Lunch at a local restaurant";
}

export function discountPct(d: TourPackagePageDetail["sidebar"]) {
  if (d.discountPercent != null) return d.discountPercent;
  if (d.priceWas != null && d.priceWas > d.price) {
    return Math.round(((d.priceWas - d.price) / d.priceWas) * 100);
  }
  return null;
}

export function scrollToSection(domId: string) {
  document.getElementById(domId)?.scrollIntoView({ behavior: "smooth", block: "start" });
  try {
    window.history.replaceState(null, "", `#${domId}`);
  } catch {
    /* ignore */
  }
}

